    emitProgress(options, { step: 'ai-index', status: 'started' });
    log('Building AI chunk index…', verbose);

    try {
      const chunks = buildChunkIndex({ analyzerResults, resources, events, logs, profile, resourceSourceFiles, helmReleases });

